-- io.open takes the modes of C's fopen
local name = os.tmpname()
os.remove(name)
local function try(mode, content)
  local f = io.open(name, mode)
  if not f then print(mode, "nil") return end
  local wok = content == nil or f:write(content)
  f:seek("set")
  local data = f:read("*a")
  f:close()
  local g = io.open(name, "rb")
  local all = g:read("*a")
  g:close()
  print(mode, "file", wok ~= nil, data, all)
end
try("w", "abc")
try("r")
try("rb")
try("r+", "X")
try("r+b", "Y")
try("rb+", "Z")
try("a", "d")
try("ab", "e")
try("a+", "f")
try("a+b", "g")
try("w+", "hij")
try("w+b", "klm")
try("wb+", "nop")
try("rw")
try("rt")
try("wbbbbb", "q")
try("r,ccs=UTF-8")
try("z")
try("")
try("+r")
try("R")
os.remove(name)
print(io.open(name, "r") == nil, io.open(name, "r+") == nil, io.open(name, "z") == nil)
local f = io.open(name, "wx")
print(f ~= nil)
f:close()
print(io.open(name, "wx") == nil, io.open(name, "w+x") == nil)
os.remove(name)
